using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Web.Script.Serialization;
namespace Pr7Editor {
internal static class SingleOriginalTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception("Single original: "+message);}
 static string Make(string root){Directory.CreateDirectory(root);string p=Path.Combine(root,"data3.big");SelfTest.MakeArchive(p,new Dictionary<string,byte[]>{{"first",new byte[]{1,2,3}},{"neighbor",new byte[]{4,5,6}}});return p;}
 static Dictionary<string,string> Hashes(string root){return Directory.GetFiles(root,"data3.*").ToDictionary(p=>p,Bytes.Hash);}
 static SaveTransaction Prepare(string path,byte value){path=Path.GetFullPath(path);var a=new Archive(path);string id=Guid.NewGuid().ToString("N");var tx=new SaveTransaction{GameRoot=Path.GetDirectoryName(path),State="applying"};foreach(string f in new[]{path,Path.ChangeExtension(path,".bh")})tx.Files.Add(new SaveTransactionFile{Original=f,Stage=f+".pr7-"+id+".tmp",Undo=f+".undo-"+id+".tmp",BeforeHash=Bytes.Hash(f)});byte[] payload=new byte[4096];new Random(value).NextBytes(payload);payload[0]=value;a.Stage(tx.Files[0].Stage,tx.Files[1].Stage,new Dictionary<string,byte[]>{{"first",payload}});foreach(var f in tx.Files)f.AfterHash=Bytes.Hash(f.Stage);return tx;}
 static void Journal(string history,SaveTransaction tx){File.WriteAllText(Path.Combine(history,"pending-save.json"),new JavaScriptSerializer().Serialize(tx));}
 internal static IEnumerable<string> Run(string output){var result=new List<string>();string work=Path.Combine(output,"single-original-"+Guid.NewGuid().ToString("N")),path=Make(work),history=Path.Combine(work,"backups");var expected=Hashes(work);string oldBig=Originals.Known["data3.big"],oldBh=Originals.Known["data3.bh"];
 try{Originals.Known["data3.big"]=expected[path];Originals.Known["data3.bh"]=expected[Path.ChangeExtension(path,".bh")];
  for(byte i=10;i<16;i++){var a=new Archive(path);Storage.Save(work,new Dictionary<Asset,byte[]>{{a.Find("first"),new byte[]{i,2,3}}},history);Check(new Archive(path).Read(new Archive(path).Find("first"))[0]==i,"latest edit saved");Check(Directory.GetDirectories(history).Length==1,"no dated history created");foreach(var item in expected)Check(Bytes.Hash(Path.Combine(history,"originals",Path.GetFileName(item.Key)))==item.Value,"pristine originals immutable");Check(!File.Exists(Path.Combine(history,"pending-save.json"))&&!Directory.GetFiles(work,"*.tmp").Any(),"temporary files removed");}
  var prior=Hashes(work);var tx=Prepare(path,42);Check(tx.Files.All(f=>f.BeforeHash!=f.AfterHash),"interruption fixture changes both BIG and BH");Journal(history,tx);File.Replace(tx.Files[0].Stage,tx.Files[0].Original,tx.Files[0].Undo);
  OriginalBackupStore.RecoverPending(work,history);foreach(var item in prior)Check(Bytes.Hash(item.Key)==item.Value,"interrupted save restores previous EDITED working copy");Check(!File.Exists(Path.Combine(history,"pending-save.json"))&&!Directory.GetFiles(work,"*.tmp").Any(),"rollback cleans temporaries");
  tx=Prepare(path,43);Journal(history,tx);File.Replace(tx.Files[0].Stage,tx.Files[0].Original,tx.Files[0].Undo);byte[] undo=File.ReadAllBytes(tx.Files[0].Undo);File.AppendAllText(tx.Files[0].Undo,"tamper");var partial=Hashes(work);bool refused=false;try{OriginalBackupStore.RecoverPending(work,history);}catch(IOException){refused=true;}Check(refused&&partial.All(p=>Bytes.Hash(p.Key)==p.Value),"tampered rollback rejected without writes");File.WriteAllBytes(tx.Files[0].Undo,undo);OriginalBackupStore.RecoverPending(work,history);
  tx=Prepare(path,44);Journal(history,tx);foreach(var f in tx.Files)File.Replace(f.Stage,f.Original,f.Undo);tx.State="complete";Journal(history,tx);OriginalBackupStore.RecoverPending(work,history);Check(new Archive(path).Read(new Archive(path).Find("first"))[0]==44,"completed save cleanup preserves new edit");
  var live=new Archive(path);Check(Originals.ReadResource(live.Find("first"),work,history).SequenceEqual(new byte[]{1,2,3}),"individual restore reads pristine original after many saves");Check(live.Read(live.Find("neighbor")).SequenceEqual(new byte[]{4,5,6}),"neighbor unchanged");
  result.Add("Respaldo unico: seis guardados conservan solo originales + copia activa, sin historial creciente; restauracion individual y vecino intactos.");
  result.Add("Transacciones: interrupcion entre BIG/BH recupera la copia editada anterior; undo alterado se rechaza sin escribir; guardado completo limpia temporales conservando la nueva edicion.");
  string migrated=Path.Combine(work,"migration");Directory.CreateDirectory(migrated);foreach(var item in expected)File.Copy(Path.Combine(history,"originals",Path.GetFileName(item.Key)),Path.Combine(migrated,Path.GetFileName(item.Key)));
  string oldHistory=Path.Combine(migrated,"backups");Directory.CreateDirectory(oldHistory);
  foreach(string date in new[]{"20000101-000000-000","20000101-000001-000"}){string folder=Path.Combine(oldHistory,date);Directory.CreateDirectory(folder);var m=new BackupManifest{GameRoot=migrated,State="complete"};foreach(var item in expected){string n=Path.GetFileName(item.Key),backup=Path.Combine(folder,n);File.Copy(Path.Combine(history,"originals",n),backup);m.Files.Add(new BackupFile{Original=Path.Combine(migrated,n),Backup=backup,BeforeHash=item.Value});}File.WriteAllText(Path.Combine(folder,"respaldo.json"),new JavaScriptSerializer().Serialize(m));}
  var edit=new Archive(Path.Combine(migrated,"data3.big"));var staged=Prepare(edit.FileName,88);foreach(var f in staged.Files){File.Replace(f.Stage,f.Original,null);}var before=Hashes(migrated);OriginalBackupStore.Compact(migrated,oldHistory);Check(Directory.GetDirectories(oldHistory).Length==1,"legacy copies consolidated");foreach(var item in before)Check(Bytes.Hash(item.Key)==item.Value,"migration preserves active edits");var restored=new Archive(Path.Combine(migrated,"data3.big"));Check(Originals.ReadResource(restored.Find("first"),migrated,oldHistory)[0]==1,"migration preserves original for resource restore");
  string blocked=Path.Combine(work,"missing-original"),blockedPath=Make(blocked),blockedHistory=Path.Combine(blocked,"backups"),badFolder=Path.Combine(blockedHistory,"20000101-000000-000");Directory.CreateDirectory(badFolder);File.WriteAllText(Path.Combine(badFolder,"respaldo.json"),"{}");foreach(var f in Prepare(blockedPath,99).Files)File.Replace(f.Stage,f.Original,null);File.Copy(blockedPath,Path.Combine(badFolder,"data3.big"));bool missing=false;try{OriginalBackupStore.Compact(blocked,blockedHistory);}catch(IOException){missing=true;}Check(missing&&Directory.Exists(badFolder),"missing original prevents cleanup");
  result.Add("Consolidacion: copias antiguas retiradas solo tras verificar originales; cambios activos conservados; si falta el original, no elimina el historial.");
  string another=Path.Combine(work,"another-game"),anotherPath=Make(another);var other=new Archive(anotherPath);string secondStore=Storage.Save(another,new Dictionary<Asset,byte[]>{{other.Find("first"),new byte[]{77,2,3}}},history);Check(!String.Equals(Path.GetFullPath(secondStore),Path.GetFullPath(Path.Combine(history,"originals")),StringComparison.OrdinalIgnoreCase),"separate installation original set");other=new Archive(anotherPath);Check(Originals.ReadResource(other.Find("first"),another,history)[0]==1,"another installation resource restore");Check(Bytes.Hash(Path.Combine(history,"originals","data3.big"))==expected[path],"first installation originals unchanged");
  result.Add("Varias instalaciones: Abrir carpeta conserva un unico conjunto original por instalacion, sin mezclar respaldos de juegos diferentes.");
 }finally{Originals.Known["data3.big"]=oldBig;Originals.Known["data3.bh"]=oldBh;}
 return result;
 }
}
}
